"use client";

import { useRef, useState } from "react";
import Link from "next/link";
import { LanguageSwitcher } from "./LanguageSwitcher";
import { useLanguage } from "./LanguageProvider";
import { actionVersion, approvalBlockers, calendarExport, canSimulate, creativeVersion, demoFans, demoMeasurement, demoPartners, demoSourceManifest, eligibleFans, generateCreative, goalLabels, rankFans, sourceLabels, validDate } from "@/lib/clubOperations";
import type { Action, Channel, Creative, Goal, Plan, Role, SourceId, SourceState } from "@/lib/clubOperations";
import sample from "../../data/seed/club-operations-demo.json";
import { ClubStrategyModules } from "./ClubStrategyModules";
import type { StrategyView } from "./ClubStrategyModules";
import { allModules, brandCampaignVersion, campaignBlockers, demoAppearances, demoBrand, demoCampaigns, demoPlayers } from "@/lib/clubStrategy";
import type { Appearance, BrandKit, Campaign, ModuleId } from "@/lib/clubStrategy";
import { ClubControlReview } from "./ClubControlReview";
import { attestReview, controlBlockers, defaultControl, demoPolicy, talentLaunchBlockers } from "@/lib/clubControl";
import type { ControlEvent, ControlSettings, Review, ReviewKind } from "@/lib/clubControl";
import { ClubJourneyHome } from "./ClubJourneyHome";
import { visibleTasks } from "@/lib/clubJourney";
import { ClubActionOverview } from "./ClubActionOverview";
import { ClubTaskCalendar } from "./ClubTaskCalendar";
import { ClubCreativeBrief } from "./ClubCreativeBrief";
import { ClubDepartmentHome } from "./ClubDepartmentHome";
import { ClubMatchContext } from "./ClubMatchContext";
import { recalculatePlan, rebaseActionCreatives } from "@/lib/clubPlanRecalculation";
import { generateContextPlan, validKickoff } from "@/lib/clubMatchContext";
import type { ClubFixture } from "@/lib/clubFixtureCalendar";
import type { Department } from "@/lib/clubDepartments";
import { findCreative, storeCreative, headlineLines } from "@/lib/clubCreativePackages";
import type { CreativePackages } from "@/lib/clubCreativePackages";
import styles from "./ClubOperationsDemo.module.css";

type View = "home" | "control" | "plan" | "flow" | "calendar" | "audiences" | "partners" | "creative" | "sources" | "results" | StrategyView;
const defaultSources: Record<SourceId, SourceState> = { ticketing: "ready", crm: "ready", access: "ready", transport: "ready", weather: "ready" };

export function ClubOperationsDemo({ fixture, fixtures }: { fixture: ClubFixture; fixtures: ClubFixture[] }) {
  const { lang } = useLanguage();
  const es = lang === "es";
  const tr = (spanish: string, english: string) => es ? spanish : english;
  const [view, setViewState] = useState<View>("home");
  const [department, setDepartment] = useState<Department>("all");
  const [excludedByFixture, setExcludedByFixture] = useState<Record<string,string[]>>({});
  const [fixtureId, setFixtureId] = useState(fixture.id);
  const [kickoff, setKickoff] = useState(fixture.kickoff);
  const [actionStep, setActionStep] = useState<"prepare" | "creative" | "control">("prepare");
  const [taskOwner, setTaskOwner] = useState("all");
  const [taskStatus, setTaskStatus] = useState("pending");
  const [taskAction, setTaskAction] = useState("all");
  const [taskPhase, setTaskPhase] = useState("all");
  const [planScenario, setPlanScenario] = useState("london");
  const [scenario, setScenario] = useState("london");
  const [date, setDate] = useState(fixture.date);
  const [goal, setGoal] = useState<Goal>("repeat");
  const [mobility, setMobility] = useState(false);
  const [comprehensive, setComprehensive] = useState(false);
  const [role, setRole] = useState<Role>("operator");
  const [sources, setSources] = useState({ ...defaultSources });
  const [plan, setPlan] = useState<Plan | null>(null);
  const [selected, setSelected] = useState<Action["id"]>("repeat");
  const [channel, setChannel] = useState<Channel>("instagram");
  const [creativePackages, setCreativePackages] = useState<CreativePackages>({});
  const creative = findCreative(creativePackages, selected, channel);
  function setCreative(value: Creative | null) { setCreativePackages(previous => storeCreative(previous, selected, channel, value)); }
  const [segment, setSegment] = useState<"all" | "subscriber" | "occasional">("all");
  const [rankMetric, setRankMetric] = useState<"attendance" | "purchases">("attendance");
  const [notice, setNotice] = useState("");
  const [activity, setActivity] = useState<string[]>([]);
  const [brand, setBrand] = useState<BrandKit>({ ...demoBrand });
  const [campaign, setCampaign] = useState<Campaign>({ ...demoCampaigns[0] });
  const [enabledModules, setEnabledModules] = useState<ModuleId[]>([...allModules]);
  const [appearances, setAppearances] = useState<Appearance[]>([...demoAppearances]);
  const [talentId, setTalentId] = useState<string | null>(null);
  const [talentActionId, setTalentActionId] = useState<Action["id"] | null>(null);
  const [control, setControl] = useState<ControlSettings>({ ...defaultControl });
  const [paused, setPaused] = useState(false);
  const [epoch, setEpoch] = useState(0);
  const [reviews, setReviews] = useState<Record<string, Review[]>>({});
  const [controlEvents, setControlEvents] = useState<ControlEvent[]>([]);
  const svgRef = useRef<SVGSVGElement>(null);
  const contextKey = `${scenario}:${fixtureId}`;
  const excludedSignals = excludedByFixture[contextKey] ?? [];
  const timeZone = scenario === "london" ? "Europe/London" : "Europe/Madrid";
  const suggestion = validDate(date) && validKickoff(kickoff) ? generateContextPlan(date,kickoff,fixtureId,goal,excludedSignals,sources,comprehensive,timeZone) : null;
  const configurationChanged = Boolean(plan && (plan.date !== date || plan.kickoff !== kickoff || plan.fixtureId !== fixtureId || JSON.stringify(plan.sourceStates) !== JSON.stringify(sources) || JSON.stringify(plan.excludedSignalIds ?? []) !== JSON.stringify([...excludedSignals].sort()) || JSON.stringify(plan.signalSnapshot ?? []) !== JSON.stringify(suggestion?.signalSnapshot ?? []) || plan.goal !== goal || plan.mobility !== mobility || plan.comprehensive !== comprehensive || planScenario !== scenario));
  const editable = role !== "viewer";
  const activeScenario = plan ? planScenario : scenario;
  const club = activeScenario === "london" ? "London City" : tr("Club español Demo", "Spanish Demo Club");
  const activeFixture = fixtures.find(item => item.id === (plan?.fixtureId ?? fixtureId)) ?? fixture;
  const opponent = activeScenario === "london" ? activeFixture.opponent : tr("Rival de prueba", "Example opponent");
  const action = plan?.actions.find((item) => item.id === selected) ?? null;
  const version = action && plan ? actionVersion(action, plan.date, sources) : "";
  const approved = Boolean(!configurationChanged && action && action.approvedVersion === version);
  const currentCreative = !configurationChanged && creative && creative.actionId === action?.id && creative.actionVersion === version ? creative : null;
  const creativeApproved = Boolean(currentCreative && currentCreative.approvedVersion === creativeVersion(currentCreative));
  const blockers = action && plan ? [...approvalBlockers(action, plan.date, sources, role), ...(configurationChanged ? ["configuration"] : [])] : [];
  const audience = action ? eligibleFans(action.id, demoFans) : [];
  const controlVersion = JSON.stringify({ epoch, action:version, creative:currentCreative ? creativeVersion(currentCreative) : null, control, policy:demoPolicy, territory:scenario === "london" ? "UK" : "ES", talentId, appearances });
  const actionReviews = reviews[selected] ?? [];
  const launchControlBlockers = action && plan ? [...controlBlockers(control, plan.date, paused, controlVersion, actionReviews, action.owner, Boolean(currentCreative)), ...talentLaunchBlockers(demoPlayers.find((p) => p.id === talentId), Boolean(currentCreative?.talent), appearances, plan.date, currentCreative?.channel ?? channel, scenario === "london" ? "UK" : "ES", control.budget)] : ["creative"];
  const ranked = rankFans(demoFans, segment, rankMetric);
  const titles: Record<View, string> = {
    home: tr("Inicio", "Home"),
    control:tr("Control y cumplimiento", "Control and compliance"),
    plan: tr("Partido", "Fixture"), flow: tr("Ficha de acción", "Action sheet"), calendar: tr("Mis tareas", "My tasks"), audiences: tr("Audiencias y fidelización", "Audiences & loyalty"), partners: tr("Partners", "Partners"), creative: tr("Estudio creativo", "Creative studio"), sources: tr("Fuentes y conexiones", "Sources & connections"), results: tr("Resultados", "Results"),
    brand:tr("Marca y recursos", "Brand & assets"), campaignKit:tr("Kits de campaña", "Campaign kits"), intelligence:tr("Contenidos y tendencias", "Content & trends"), talent:tr("Talento y derechos", "Talent & rights"), licence:tr("Licencia y módulos", "Licence & modules"),
  };
  const blockerText: Record<string, string> = {
    configuration: tr("Aplica o descarta los cambios del partido antes de aprobar.", "Apply or discard fixture changes before approval."),
    role: tr("Selecciona el rol de aprobación del ensayo.", "Select the rehearsal approver role."), date: tr("Falta una fecha válida.", "A valid date is required."), audience: tr("Confirma audiencia y exclusiones del ensayo.", "Confirm rehearsal audience and exclusions."), owner: tr("Asigna un responsable de la acción.", "Assign an action owner."), measurement: tr("Confirma el criterio de medición.", "Confirm the measurement criteria."), rights: tr("Confirma los derechos del partner en el ensayo.", "Confirm partner rights in the rehearsal."), sources: tr("Restaura las fuentes necesarias a estado de prueba disponible.", "Restore required sources to available test data."),
  };
  const ownerOptions = <><option value="">{tr("Sin asignar", "Unassigned")}</option><option value="marketing">{tr("Responsable Demo · Marketing", "Demo owner · Marketing")}</option><option value="communications">{tr("Responsable Demo · Comunicación", "Demo owner · Communications")}</option><option value="ticketing">{tr("Responsable Demo · Ticketing", "Demo owner · Ticketing")}</option><option value="business">{tr("Negocio", "Business")}</option><option value="partnerships">{tr("Responsable Demo · Partners", "Demo owner · Partnerships")}</option></>;

  function recordControl(event: string, actor: string, evidence = "") {
    setControlEvents((previous) => [...previous, { id:previous.length + 1, at:new Date().toISOString(), action:action?.id ?? "all", event, version:controlVersion, actor, evidence }]);
  }
  function invalidateControls() { setReviews({}); setEpoch((value) => value + 1); }
  function reviewControl(kind: ReviewKind, reviewer: string, evidence: string) {
    if (!action || !currentCreative || paused) return;
    const review = attestReview(kind, controlVersion, action.owner, reviewer, evidence, role, new Date().toISOString());
    if (!review) return;
    setReviews((previous) => ({ ...previous, [selected]:[...(previous[selected] ?? []).filter((r) => r.kind !== kind),review] }));
    recordControl("review:" + kind,reviewer,evidence);
  }
  function log(message: string) { setNotice(message); setActivity((previous) => [message, ...previous].slice(0, 12)); }
  function invalidateStrategy(nextBrand = brand, nextCampaign = campaign, nextTalent: string | null = talentId) {
    invalidateControls();
    setCreativePackages({});
    setPlan((previous) => previous ? { ...previous, actions:previous.actions.map((item) => ({ ...item, strategyVersion:JSON.stringify({ kits:brandCampaignVersion(nextBrand,nextCampaign), talent:nextTalent }), approvedVersion:null, simulatedVersion:null })) } : null);
  }
  function clearPlan() { setNotice(plan ? tr("Cambios pendientes. Conservamos el plan anterior hasta que confirmes la regeneración.", "Pending changes. The previous plan is kept until you confirm regeneration.") : tr("Propuesta recalculada desde el contexto. Todavía no hay un borrador generado.", "Proposal recalculated from context. No draft has been generated yet.")); }
  function go(next: View) {
    if (next === "creative" || next === "control") { setActionStep(next); setViewState("flow"); }
    else { if (next === "flow") setActionStep("prepare"); setViewState(next); }
  }
  function openAction(id: Action["id"]) {
    setSelected(id);
    go("flow");
  }
  function build() {
    if (!editable || !suggestion) return;
    const next = { ...suggestion, actions:suggestion.actions.map(item=>({ ...item, fixtureContext:{fixtureId,kickoff,timeZone}, strategyVersion:JSON.stringify({ kits:brandCampaignVersion(brand,campaign),talent:talentId }) })) };
    const result = recalculatePlan(planScenario===scenario ? plan : null,next,creativePackages,sources);
    const replacing = Boolean(plan && (planScenario!==scenario || plan.fixtureId!==fixtureId || plan.timeZone!==timeZone));
    if (plan && !window.confirm(replacing ? tr("Cambiar de partido o club sustituye el borrador y su trabajo en esta sesión. ¿Continuar?", "Changing fixture or club replaces this session's draft and work. Continue?") : tr("Se conserva el trabajo de las acciones vigentes. Las modificadas necesitan nueva revisión; las que desaparecen se retiran con sus tareas y piezas. ¿Aplicar los cambios?", "Work on retained actions is preserved. Changed actions need review; removed actions lose their tasks and assets. Apply changes?"))) return;
    setPlanScenario(scenario);
    setTaskAction("all"); setTaskPhase("all");
    setReviews(previous=>Object.fromEntries(Object.entries(previous).filter(([id])=>result.unchangedIds.includes(id as Action["id"]))));
    setPlan(result.plan); setCreativePackages(result.creatives);
    setSelected(result.plan.actions.some(item=>item.id===selected) ? selected : result.plan.actions[0].id);
    log(plan ? tr("Borrador actualizado. Trabajo conservado en las acciones vigentes; revisa las acciones modificadas antes de aprobar.", "Draft updated. Work on retained actions preserved; review changed actions before approval.") : tr("Borrador generado desde el calendario y las señales activas de prueba. Todas las acciones requieren revisión.", "Draft generated from the calendar and active test signals. Every action requires review."));
  }

  function patchAction(patch: Partial<Pick<Action, "owner" | "measurement" | "audienceReviewed" | "rights">>) {
    if (!editable || !action) return;
    invalidateControls();
    const updated = { ...action, ...patch, approvedVersion:null, simulatedVersion:null };
    setPlan((previous) => previous ? { ...previous, actions: previous.actions.map((item) => item.id === selected ? updated : item) } : null);
    if (plan) setCreativePackages(previous=>rebaseActionCreatives(previous,updated,plan.date,sources));
  }
  function approveAction() {
    if (!action || !plan || blockers.length || approved) return;
    setPlan({ ...plan, actions: plan.actions.map((item) => item.id === selected ? { ...item, approvedVersion: version } : item) });
    log(tr("Acción aprobada en el ensayo. Falta revisar sus creatividades.", "Action approved in rehearsal. Its creatives still require review."));
  }
  function makeCreative() {
    if (!editable || !action || !plan || !approved || !enabledModules.includes("studio") || campaignBlockers(brand,campaign,plan.date).length) return;
    if (creative && !window.confirm(tr("Regenerar sustituirá el texto editado y la aprobación de este canal. Los otros paquetes se conservarán. ¿Continuar?", "Regenerating replaces edited copy and approval for this channel. Other packages are kept. Continue?"))) return;
    invalidateControls();
    setCreative(generateCreative(action, version, channel, club, opponent, plan.date, lang, { name:campaign.name[lang], headline:campaign.headline[lang], brief:campaign.brief[lang], talent:selected === talentActionId ? demoPlayers.find((p) => p.id === talentId)?.name : undefined }));
    log(tr("Paquete generado desde una plantilla: texto, composición gráfica y guion. No se ha usado un modelo de IA ni renderizado un vídeo.", "Template package generated: copy, graphic composition and script. No AI model was used and no video was rendered."));
  }
  function approveCreative() {
    if (role !== "approver" || !approved || !currentCreative || blockers.length || !currentCreative.text.trim() || campaignBlockers(brand,campaign,date).length || !enabledModules.includes("studio")) return;
    setCreative({ ...currentCreative, approvedVersion: creativeVersion(currentCreative) });
    log(tr("Versión de la creatividad aprobada en el ensayo.", "Creative version approved in rehearsal."));
  }
  function simulate() {
    if (!action || !plan || !canSimulate(action, plan.date, sources, role, currentCreative) || launchControlBlockers.length || !enabledModules.includes("automation") || !enabledModules.includes("studio") || campaignBlockers(brand,campaign,date).length) return;
    setPlan({ ...plan, actions: plan.actions.map((item) => item.id === selected ? { ...item, simulatedVersion: version } : item) });
    recordControl("launch-simulated", role, "NO-LIVE-DELIVERY");
    log(tr("Simulación completada una vez para esta versión. No se han enviado mensajes, publicado piezas ni gastado presupuesto.", "Simulation completed once for this version. No messages sent, posts published or budget spent."));
    go("results");
  }
  function download(content: string, filename: string, type: string) {
    const url = URL.createObjectURL(new Blob([content], { type }));
    const link = document.createElement("a"); link.href = url; link.download = filename; link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  function reset() {
    if (plan && !window.confirm(tr("Se borrará el trabajo de esta sesión de prueba. ¿Reiniciar la demo?", "This clears the current rehearsal session. Reset demo?"))) return;
    setTalentActionId(null); setControl({ ...defaultControl }); setPaused(false); setReviews({}); setEpoch(0); setControlEvents([]);
    setBrand({ ...demoBrand }); setCampaign({ ...demoCampaigns[0] }); setEnabledModules([...allModules]); setAppearances([...demoAppearances]); setTalentId(null);
    setExcludedByFixture({}); setFixtureId(fixture.id); setKickoff(fixture.kickoff); setDepartment("all"); setPlanScenario("london"); setTaskOwner("all"); setTaskStatus("pending"); setTaskAction("all"); setTaskPhase("all");
    setScenario("london"); setDate(fixture.date); setGoal("repeat"); setMobility(false); setComprehensive(false); setRole("operator"); setSources({ ...defaultSources }); setPlan(null); setCreativePackages({}); setSelected("repeat"); setChannel("instagram"); setSegment("all"); setRankMetric("attendance"); setActivity([]); go("home"); setNotice(tr("Demo reiniciada.", "Demo reset."));
  }
  const empty = <section className={styles.panel}><h2>{tr("Primero genera un plan", "Generate a plan first")}</h2><p>{tr("Elige un objetivo y una fecha. Después podrás asignar, aprobar y ensayar cada acción.", "Choose an objective and date. Then assign, approve and rehearse each action.")}</p><button type="button" className={styles.primary} onClick={() => go("plan")}>{tr("Ir al plan", "Open plan")}</button></section>;
  const actionPicker = plan ? <label className={styles.picker}>{tr("Acción de trabajo", "Current action")}<select value={selected} onChange={(event) => { setSelected(event.target.value as Action["id"]); }}>{plan.actions.map((item) => <option value={item.id} key={item.id}>{item.title[lang]}</option>)}</select></label> : null;

  return <main className={styles.shell}>
    <header className={styles.topbar}><Link href="/for-clubs">AVELA</Link><div><LanguageSwitcher /><button type="button" onClick={reset}>{tr("Reiniciar demo", "Reset demo")}</button></div></header>
    <aside className={styles.notice}><strong>{tr("DEMO PÚBLICA · DATOS SINTÉTICOS · SIN ENVÍOS REALES", "PUBLIC DEMO · SYNTHETIC DATA · NO LIVE DELIVERY")}</strong><p>{tr("Ensayo sin envíos reales. No introduzcas datos privados. Los cambios se pierden al recargar.", "Rehearsal with no live delivery. Do not enter private data. Changes reset on reload.")}</p></aside>
    <div className={styles.layout}>
      <aside className={styles.sidebar}><p className={styles.eyebrow}>AVELA</p><h2>{club}</h2><nav aria-label={tr("Operación del club", "Club operations")}>{(["home","plan","flow","calendar","audiences","partners","results"] as View[]).map((key) => <button key={key} type="button" aria-current={view === key ? "page" : undefined} className={view === key ? styles.active : ""} onClick={() => { go(key); setNotice(""); }}>{key === "flow" ? tr("Acciones", "Actions") : titles[key]}</button>)}</nav><details><summary>{tr("Recursos", "Resources")}</summary>{(["brand","campaignKit","intelligence","talent"] as View[]).map(key => <button type="button" key={key} onClick={() => go(key)}>{titles[key]}</button>)}</details><details><summary>{tr("Configuración", "Settings")}</summary>{(["sources","licence"] as View[]).map(key => <button type="button" key={key} onClick={() => go(key)}>{titles[key]}</button>)}</details><p><Link href="/club-demo/permissions">{tr("Usuarios y permisos →", "Team permissions →")}</Link></p><label>{tr("Rol simulado", "Simulated role")}<select value={role} onChange={(event) => setRole(event.target.value as Role)}><option value="operator">{tr("Operaciones", "Operator")}</option><option value="approver">{tr("Aprobación", "Approver")}</option><option value="viewer">{tr("Solo lectura", "Read only")}</option></select></label><p>{tr("Prueba de interfaz; no son permisos de acceso reales.", "Interface rehearsal; these are not real access permissions.")}</p></aside>
      <section className={styles.content} aria-label={titles[view]}><header className={styles.pageHead}><p className={styles.eyebrow}>{tr("OPERACIÓN POR PARTIDO", "MATCHDAY OPERATIONS")}</p><h1>{titles[view]}</h1><p>{view === "plan" ? (scenario === "london" ? "London City" : tr("Club español Demo", "Spanish Demo Club")) : club} · {view === "plan" ? (scenario === "london" ? (fixtures.find(f=>f.id===fixtureId)?.opponent ?? fixture.opponent) : tr("Rival de prueba", "Example opponent")) : opponent} · {view === "plan" ? date : (plan?.date ?? (date || "—"))} · {view === "plan" ? kickoff : (plan?.kickoff ?? kickoff)} · {view === "plan" ? timeZone : (activeScenario === "london" ? "Europe/London" : "Europe/Madrid")}</p></header><p className={styles.status} role="status" aria-live="polite">{notice}</p>

        {configurationChanged && <section className={styles.warning} aria-label={tr("Cambios pendientes", "Pending changes")}><p>{tr("Has cambiado la configuración. El plan anterior sigue disponible; no se puede aprobar ni lanzar con cambios pendientes.", "Configuration changed. The previous plan remains available; approval and delivery are blocked until changes are resolved.")}</p><button type="button" onClick={() => go("plan")}>{tr("Revisar cambios del partido", "Review fixture changes")}</button><button type="button" onClick={() => { if (plan) { if (plan.sourceStates) setSources({ ...plan.sourceStates }); setScenario(planScenario); setFixtureId(plan.fixtureId ?? fixture.id); setKickoff(plan.kickoff ?? fixture.kickoff); setExcludedByFixture(previous => ({ ...previous,[`${planScenario}:${plan.fixtureId ?? fixture.id}`]:plan.excludedSignalIds ?? [] })); setDate(plan.date); setGoal(plan.goal); setMobility(plan.mobility); setComprehensive(plan.comprehensive); setNotice(""); } }}>{tr("Descartar cambios", "Discard changes")}</button></section>}
        {view === "home" && <ClubJourneyHome es={es} opponent={opponent} date={date} plan={plan} sources={sources} onPlan={() => go("plan")} onTasks={() => { setTaskOwner("all"); setTaskStatus("pending"); setTaskAction("all"); setTaskPhase("all"); go("calendar"); }} onAction={openAction} departmentPanel={<ClubDepartmentHome department={department} lang={lang} plan={plan} onDepartment={setDepartment} onArea={go} onTasks={(owner) => { setTaskOwner(owner); setTaskStatus("pending"); setTaskAction("all"); setTaskPhase("all"); go("calendar"); }} />} />}
        {view === "flow" && plan && <section className={styles.panel}><h2>{action?.title[lang]}</h2>{action && <ClubActionOverview action={action} date={plan.date} lang={lang} sources={sources} onTasks={() => { setTaskAction(action.id); setTaskOwner("all"); setTaskStatus("all"); setTaskPhase("all"); go("calendar"); }} />}<p>{tr("Prepara, revisa y continúa sin salir de esta ficha. Las pestañas muestran el mismo trabajo, no campañas distintas.", "Prepare, review and continue within this sheet. Tabs show the same work, not separate campaigns.")}</p><nav className={styles.actions} aria-label={tr("Pasos de la acción", "Action steps")}>{(["prepare","creative","control"] as const).map((step,index) => <button type="button" key={step} aria-current={actionStep === step ? "step" : undefined} className={actionStep === step ? styles.primary : ""} onClick={() => setActionStep(step)}>{index + 1}. {step === "prepare" ? tr("Preparación", "Preparation") : step === "creative" ? tr("Piezas y lanzamiento", "Assets and delivery") : tr("Controles", "Checks")}</button>)}</nav><p>{tr("Siguiente paso", "Next step")}: {action?.simulatedVersion === version ? tr("simulación completada; consulta el registro en Resultados.", "simulation complete; inspect the Results log.") : !approved ? tr("completa los requisitos y solicita aprobación en Preparación.", "complete prerequisites and request approval in Preparation.") : !currentCreative ? tr("prepara las piezas de la acción.", "prepare the action assets.") : !creativeApproved ? tr("revisa y aprueba la versión de la pieza.", "review and approve the asset version.") : launchControlBlockers.length ? tr("resuelve las revisiones pendientes en Controles.", "resolve pending reviews in Checks.") : tr("todo está revisado; puedes simular el lanzamiento sin enviar.", "all checks are complete; simulate delivery without sending.")}</p></section>}
        {(["brand","campaignKit","intelligence","talent","licence"] as string[]).includes(view) && <ClubStrategyModules key={scenario} view={view as StrategyView} lang={lang} date={date} role={role} brand={brand} campaign={campaign} enabled={enabledModules} appearances={appearances} onBrand={(value) => { setBrand(value); invalidateStrategy(value,campaign); log(tr("Marca modificada: revisa las acciones y piezas afectadas.", "Brand changed: review affected actions and creatives.")); }} onCampaign={(value) => { setCampaign(value); invalidateStrategy(brand,value); log(tr("Campaña modificada sin cambiar la identidad base. Revisiones reiniciadas.", "Campaign changed without modifying the base identity. Reviews reset.")); }} onModules={(value) => { setEnabledModules(value); setTalentId(null); invalidateStrategy(brand,campaign,null); log(tr("Alcance de prueba actualizado; no se ha contratado nada. Revisiones reiniciadas.", "Test scope updated; no purchase made. Reviews reset.")); }} onAppearances={(value,playerId) => { setAppearances(value); setTalentId(playerId ?? null); setTalentActionId(playerId ? selected : null); invalidateStrategy(brand,campaign,playerId ?? null); }} onDownload={download} onNotice={log} />}
        {(view === "flow" && actionStep === "control") && <>{actionPicker}<ClubControlReview es={es} role={role} owner={action?.owner ?? ""} version={controlVersion} settings={control} paused={paused} reviews={actionReviews} events={controlEvents} blockers={launchControlBlockers} hasAction={Boolean(action)} onSettings={(value) => { if (!editable) return; setControl(value); invalidateControls(); recordControl("policy-settings-changed",role,"SYNTHETIC"); }} onReview={reviewControl} onPause={() => { if (!editable) return; setPaused(!paused); invalidateControls(); recordControl(paused ? "resume-requires-new-reviews" : "pause-all-actions",role,"DEMO-INCIDENT"); }} onRevoke={() => { if (role !== "approver" || !action) return; setReviews((previous) => ({ ...previous, [selected]:[] })); recordControl("reviews-revoked",role,"DEMO-REVOCATION"); }} onExport={() => download(JSON.stringify({ synthetic:true, persistent:false, policy:demoPolicy, settings:control, paused, action:action?.id ?? null, version:controlVersion, reviews:actionReviews, blockers:launchControlBlockers, events:controlEvents },null,2),"club-demo-control-dossier.json","application/json")} /></>}
        {view === "audiences" && !enabledModules.includes("audiences") && <section className={styles.panel}><h2>{tr("Audiencias · módulo adicional", "Audiences · additional module")}</h2><p>{tr("Actívalo en Licencia y módulos para ensayar segmentos, rankings y fidelización.", "Enable it in Licence & modules to rehearse segments, rankings and loyalty.")}</p><button type="button" onClick={() => go("licence")}>{tr("Configurar alcance", "Configure scope")}</button></section>}
        {view === "flow" && actionStep === "creative" && !enabledModules.includes("studio") && <section className={styles.panel}><h2>{tr("Estudio creativo · módulo adicional", "Creative studio · additional module")}</h2><p>{tr("Los kits y briefings siguen incluidos en la base. Añade Estudio creativo para generar piezas de prueba.", "Kits and briefs remain included in base. Add Creative studio to generate test assets.")}</p><button type="button" onClick={() => go("licence")}>{tr("Configurar alcance", "Configure scope")}</button></section>}

        {view === "plan" && <>
          <section className={styles.panel}><h2>{tr("Prepara la estrategia del partido", "Prepare the matchday strategy")}</h2><div className={styles.fields}>
            <label>{tr("Escenario", "Scenario")}<select value={scenario} disabled={!editable} onChange={(event) => { setScenario(event.target.value); setFixtureId(event.target.value === "london" ? fixture.id : "spain-demo"); setKickoff(event.target.value === "london" ? fixture.kickoff : "16:00"); setDate(event.target.value === "london" ? fixture.date : "2026-10-25"); clearPlan(); }}><option value="london">London City · {tr("piloto de demostración", "demonstration pilot")}</option><option value="spain">{tr("Club español · escenario ficticio de Segunda", "Spanish club · fictional second-tier scenario")}</option></select></label>
            {scenario === "london" && <label>{tr("Partidos en casa · calendario cargado", "Home fixtures · stored calendar")}<select value={fixtureId} disabled={!editable} onChange={event => { const item = fixtures.find(f=>f.id===event.target.value); if (!item) return; setFixtureId(item.id); setDate(item.date); setKickoff(item.kickoff); clearPlan(); }}>{fixtures.map(item=><option key={item.id} value={item.id}>{item.date} · {item.kickoff || tr("Hora pendiente", "Time pending")} · {item.opponent}</option>)}{!fixtures.length && <option value={fixture.id}>{tr("Sin próximos partidos cargados; introduce fecha y hora", "No upcoming fixtures stored; enter date and time")}</option>}</select></label>}
            <label>{tr("Fecha de ensayo", "Rehearsal date")}<input type="date" value={date} min="2026-01-01" max="2030-12-31" disabled={!editable} onChange={(event) => { setDate(event.target.value); clearPlan(); }} /></label>
            <label>{tr("Hora del partido", "Kickoff time")}<input type="time" value={kickoff} disabled={!editable} onChange={event => { setKickoff(event.target.value); clearPlan(); }} />{timeZone}</label>
            <label>{tr("Objetivo principal", "Primary objective")}<select value={goal} disabled={!editable} onChange={(event) => { setGoal(event.target.value as Goal); clearPlan(); }}>{(Object.keys(goalLabels) as Goal[]).map((id) => <option key={id} value={id}>{goalLabels[id][lang]}</option>)}</select></label>
          </div><label className={styles.check}><input type="checkbox" checked={comprehensive} disabled={!editable} onChange={(event) => { setComprehensive(event.target.checked); clearPlan(); }} />{tr("Plan integral: captación, recurrencia, asistencia, partners y fidelización", "Complete plan: acquisition, repeat visits, attendance, partners and loyalty")}</label><p>{tr("El calendario propone el próximo partido en casa. Puedes corregir su fecha y hora; el motor calcula el borrador desde las señales activas. Las tareas son días completos, sin hora de envío.", "The calendar proposes the next home fixture. Correct its date and time if needed; the engine calculates a draft from enabled signals. Tasks are all-day, without sending times.")}</p></section>
          <ClubMatchContext lang={lang} date={date} kickoff={kickoff} timeZone={timeZone} plan={plan} suggestion={suggestion} changed={configurationChanged} editable={editable} excluded={excludedSignals} onPrepare={build} onToggle={id => { if (!editable) return; setExcludedByFixture(previous => { const current = previous[contextKey] ?? []; return { ...previous,[contextKey]:current.includes(id) ? current.filter(value=>value!==id) : [...current,id] }; }); clearPlan(); }} />
          {plan && <><div className={styles.metrics}><article><span>{tr("Acciones propuestas", "Proposed actions")}</span><strong>{plan.actions.length}</strong></article><article><span>{tr("Tareas generadas", "Generated tasks")}</span><strong>{plan.actions.flatMap((item) => item.tasks).length}</strong></article><article><span>{tr("Aprobadas en ensayo", "Approved in rehearsal")}</span><strong>{plan.actions.filter((item) => item.approvedVersion === actionVersion(item, plan.date, sources)).length}</strong></article></div><div className={styles.cards}>{plan.actions.map((item) => <article key={item.id} className={styles.panel}><span className={styles.badge}>{tr("Propuesta de prueba", "Test proposal")}</span><h2>{item.title[lang]}</h2><p>{item.reason[lang]}</p><p><strong>{tr("Medición: ", "Measurement: ")}</strong>{item.kpi[lang]}</p><button type="button" onClick={() => openAction(item.id)}>{tr("Preparar esta acción", "Prepare this action")} →</button></article>)}</div></>}
          <section className={styles.panel}><h2>{tr("Recorrido de la demo", "Demo journey")}</h2><ol><li>{tr("Genera el plan y abre una acción.", "Generate the plan and open an action.")}</li><li>{tr("Asigna responsable y confirma medición; cambia al rol de aprobación.", "Assign an owner and confirm measurement; switch to the approver role.")}</li><li>{tr("Aprueba la acción y genera su paquete creativo.", "Approve the action and generate its creative package.")}</li><li>{tr("Revisa la pieza, apruébala y simula el lanzamiento.", "Review the creative, approve it and simulate launch.")}</li><li>{tr("Explora calendario, audiencias, partners y resultados de prueba.", "Explore calendar, audiences, partners and test results.")}</li></ol></section>
        </>}

        {view === "flow" && actionStep === "prepare" && (action && plan ? <>{actionPicker}<section className={styles.panel}><span className={styles.badge}>{approved ? tr("Aprobada en ensayo", "Approved in rehearsal") : tr("Pendiente de revisión", "Awaiting review")}</span><h2>{action.title[lang]}</h2><button type="button" onClick={() => go("control")}>{tr("Abrir ficha de control de esta acción", "Open this action’s control sheet")}</button><p>{action.reason[lang]}</p><dl className={styles.facts}><div><dt>{tr("Audiencia", "Audience")}</dt><dd>{action.audience[lang]}</dd></div><div><dt>{tr("Criterio de resultado", "Outcome criteria")}</dt><dd>{action.kpi[lang]}</dd></div></dl>
          <div className={styles.fields}><label>{tr("Responsable de la acción", "Action owner")}<select value={action.owner} disabled={!editable} onChange={(event) => patchAction({ owner: event.target.value })}>{ownerOptions}</select></label></div><label className={styles.check}><input type="checkbox" checked={action.audienceReviewed} disabled={!editable} onChange={(event) => patchAction({ audienceReviewed: event.target.checked })} />{tr("Confirmar audiencia y exclusiones de prueba", "Confirm test audience and exclusions")}</label><label className={styles.check}><input type="checkbox" checked={action.measurement} disabled={!editable} onChange={(event) => patchAction({ measurement: event.target.checked })} />{tr("Confirmar KPI y comparación de prueba", "Confirm test KPI and comparison")}</label>{action.id === "partners" && <label className={styles.check}><input type="checkbox" checked={action.rights} disabled={!editable} onChange={(event) => patchAction({ rights: event.target.checked })} />{tr("Simular revisión de derechos y exclusividades del partner", "Simulate partner rights and exclusivity review")}</label>}
          <h3>{tr("Condiciones del flujo", "Workflow conditions")}</h3><ol><li>{tr("Comprobar las fuentes necesarias y la audiencia elegible.", "Check required sources and eligible audience.")}</li><li>{tr("Revisar responsable, medición y aprobación de la acción.", "Review owner, measurement and action approval.")}</li><li>{tr("Generar, editar y aprobar una versión creativa.", "Generate, edit and approve a creative version.")}</li><li>{tr("Ensayar una ejecución; detener recordatorios tras compra y evitar duplicados en producción.", "Rehearse one execution; production must stop reminders after purchase and prevent duplicates.")}</li></ol><p>{tr("El ensayo muestra elegibilidad, bloqueos y versiones. Los eventos de compra, bajas y envíos en tiempo real requieren conectores de producción.", "The rehearsal demonstrates eligibility, blockers and versions. Live purchase, opt-out and delivery events require production connectors.")}</p>
          {blockers.length > 0 && <div className={styles.warning}><strong>{tr("Pendiente antes de aprobar", "Required before approval")}</strong><ul>{blockers.map((id) => <li key={id}>{blockerText[id]}</li>)}</ul></div>}<div className={styles.actions}><button type="button" className={styles.primary} disabled={blockers.length > 0 || approved} onClick={approveAction}>{approved ? tr("Acción aprobada", "Action approved") : tr("Aprobar acción de prueba", "Approve test action")}</button><button type="button" disabled={!approved} onClick={() => go("creative")}>{tr("Continuar con las piezas", "Continue with assets")}</button></div>
          <p>{tr("Cambiar responsable, medición, fecha o una fuente necesaria exige nueva revisión. Esta aprobación no autoriza envíos reales.", "Changing owner, measurement, date or a required source requires a new review. This approval does not authorise real delivery.")}</p></section></> : empty)}

        {view === "calendar" && (plan ? <><section className={styles.panel}><h2>{tr("Trabajo del equipo", "Team work")}</h2><div className={styles.fields}><label>{tr("Acción del calendario", "Calendar action")}<select value={taskAction} onChange={event => setTaskAction(event.target.value)}><option value="all">{tr("Todas las acciones", "All actions")}</option>{plan.actions.map(item => <option value={item.id} key={item.id}>{item.title[lang]}</option>)}</select></label><label>{tr("Fase del partido", "Fixture phase")}<select value={taskPhase} onChange={event => setTaskPhase(event.target.value)}><option value="all">{tr("Todas las fases", "All phases")}</option><option value="before">{tr("Antes del partido", "Before the fixture")}</option><option value="matchday">{tr("Día del partido", "Matchday")}</option><option value="after">{tr("Después del partido", "After the fixture")}</option></select></label><label>{tr("Responsable de las tareas", "Task owner")}<select value={taskOwner} onChange={event => setTaskOwner(event.target.value)}><option value="all">{tr("Todo el equipo", "Whole team")}</option><option value="unassigned">{tr("Sin asignar", "Unassigned")}</option><option value="marketing">Marketing</option><option value="communications">{tr("Comunicación", "Communications")}</option><option value="ticketing">Ticketing</option><option value="business">{tr("Negocio", "Business")}</option><option value="partnerships">Partners</option></select></label><label>{tr("Estado de las tareas", "Task status")}<select value={taskStatus} onChange={event => setTaskStatus(event.target.value)}><option value="pending">{tr("Pendientes", "Pending")}</option><option value="done">{tr("Completadas", "Done")}</option><option value="all">{tr("Todas", "All")}</option></select></label></div><p>{tr("Filtro de ensayo, no identificación de un usuario real.", "Rehearsal filter, not real user identification.")} {visibleTasks(plan, taskOwner, taskStatus, taskAction, taskPhase).length} {visibleTasks(plan, taskOwner, taskStatus, taskAction, taskPhase).length === 1 ? tr("tarea visible", "visible task") : tr("tareas visibles", "visible tasks")}</p><p>{tr("Asignación y estados locales de prueba. La conexión con herramientas de tareas está pendiente; puedes exportar este calendario de ensayo.", "Local test assignments and statuses. Task-tool integration is pending; export this rehearsal calendar.")}</p><button type="button" onClick={() => download(calendarExport(plan, lang), "club-demo-calendar.ics", "text/calendar;charset=utf-8")}>{tr("Descargar calendario de prueba (.ics)", "Download test calendar (.ics)")}</button></section><ClubTaskCalendar plan={plan} lang={lang} owner={taskOwner} status={taskStatus} actionId={taskAction} phase={taskPhase} editable={editable} onAction={openAction} onOwner={(id, owner) => { if (!editable) return; setPlan(previous => previous ? { ...previous, actions: previous.actions.map(item => ({ ...item, tasks: item.tasks.map(entry => entry.id === id ? { ...entry, owner, done: owner ? entry.done : false } : entry) })) } : null); }} onDone={(id, done) => { if (!editable) return; setPlan(previous => previous ? { ...previous, actions: previous.actions.map(item => ({ ...item, tasks: item.tasks.map(entry => entry.id === id && entry.owner ? { ...entry, done } : entry) })) } : null); }} /></> : empty)}

        {view === "audiences" && enabledModules.includes("audiences") && <><section className={styles.panel}><h2>{tr("Identidad y segmentos de prueba", "Test identity and segments")}</h2><p>{tr("Siete IDs ficticios. El ID une ejemplos de compras y visitas del mismo registro; no se han identificado personas reales. Comprador, beneficiario y asistente deben reconciliarse por separado en producción.", "Seven fictional IDs. The ID joins example purchases and visits for the same record; no real people have been identified. Buyer, beneficiary and attendee must be reconciled separately in production.")}</p><div className={styles.fields}><label>{tr("Segmento", "Segment")}<select value={segment} onChange={(event) => setSegment(event.target.value as typeof segment)}><option value="all">{tr("Todos", "All")}</option><option value="subscriber">{tr("Abonados", "Season-pass holders")}</option><option value="occasional">{tr("Compradores ocasionales", "Occasional buyers")}</option></select></label><label>{tr("Ordenar por", "Rank by")}<select value={rankMetric} onChange={(event) => setRankMetric(event.target.value as typeof rankMetric)}><option value="attendance">{tr("Asistencia reconciliada", "Reconciled attendance")}</option><option value="purchases">{tr("Compras", "Purchases")}</option></select></label></div><div className={styles.tableWrap}><table><caption>{tr("Ranking interno sintético; no es una clasificación de aficionados", "Synthetic internal ranking; not a fan leaderboard")}</caption><thead><tr><th>ID</th><th>{tr("Segmento", "Segment")}</th><th>{tr("Compras", "Purchases")}</th><th>{tr("Asistencia", "Attendance")}</th><th>{tr("Contacto", "Contact")}</th></tr></thead><tbody>{ranked.map(({ fan }) => <tr key={fan.id}><td>{fan.id}</td><td>{fan.segment === "subscriber" ? tr("Abonado", "Season pass") : tr("Ocasional", "Occasional")}</td><td>{fan.purchases}</td><td>{fan.reconciled ? `${fan.visits} / ${fan.eligibleMatches}` : tr("Sin reconciliar", "Unreconciled")}</td><td>{!fan.optedIn ? tr("Sin permiso", "No opt-in") : fan.recentContacts >= 2 ? tr("Límite alcanzado", "Contact cap") : tr("Elegible en ejemplo", "Eligible in example")}</td></tr>)}</tbody></table></div></section>
          <section className={styles.panel}><h2>{tr("Audiencia de la acción seleccionada", "Selected action audience")}</h2>{action ? <><p>{action.title[lang]} · {audience.length} {tr("registros elegibles según las reglas de prueba", "eligible records under test rules")}</p><p>{audience.map((fan) => fan.id).join(" · ") || tr("Esta acción necesita definir una audiencia propia; no inventamos destinatarios.", "This action requires its own audience definition; recipients are not fabricated.")}</p></> : <p>{tr("Genera un plan para comprobar sus exclusiones.", "Generate a plan to inspect exclusions.")}</p>}</section>
          <section className={styles.panel}><h2>{tr("Reto de fidelización · propuesta", "Loyalty challenge · proposal")}</h2><p>{tr("Propuesta: reconocer tres visitas confirmadas dentro del programa. Los accesos sin reconciliar no conceden puntos. Participación voluntaria, condiciones y recompensa deben aprobarse antes de operar.", "Proposal: recognise three confirmed visits within the programme. Unreconciled access earns no points. Voluntary participation, terms and reward require approval before operation.")}</p><p>{demoFans.filter((fan) => fan.reconciled && fan.visits >= 3).map((fan) => fan.id).join(" · ")} · {tr("cumplen el criterio sintético; ninguna recompensa emitida", "meet the synthetic criterion; no rewards issued")}</p></section></>}

        {view === "partners" && <><section className={styles.panel}><h2>{tr("Oportunidades y derechos", "Opportunities and rights")}</h2><p>{tr("Empresas ficticias para ensayar una propuesta comercial. La afinidad no confirma interés, contrato ni derechos de uso.", "Fictional businesses for rehearsing a commercial proposal. Fit does not establish interest, a contract or usage rights.")}</p></section><div className={styles.cards}>{demoPartners.map((partner) => <article className={styles.panel} key={partner.id}><span className={styles.badge}>{tr("Partner ficticio", "Fictional partner")}</span><h2>{partner.name}</h2><p>{partner.category === "mobility" ? tr("Afinidad propuesta: facilitar la llegada al estadio con información y servicios verificados.", "Proposed fit: make stadium travel easier with verified information and services.") : tr("Afinidad propuesta: participación voluntaria y beneficios para próximas visitas.", "Proposed fit: voluntary participation and benefits for future visits.")}</p><ul><li>{tr("Interés comercial: no confirmado", "Commercial interest: unconfirmed")}</li><li>{tr("Contrato y exclusividades: pendientes", "Contract and exclusivity: pending")}</li><li>{tr("Medición: participación y entregables; contactos sin compartir", "Measurement: participation and deliverables; no contact sharing")}</li></ul><button type="button" disabled={!editable || !validDate(date) || !validKickoff(kickoff)} onClick={() => { invalidateControls(); setGoal("partners"); setComprehensive(false); setPlan(generateContextPlan(date,kickoff,fixtureId,"partners",excludedSignals,sources,false,timeZone)); setSelected("partners"); setCreativePackages({}); go("flow"); log(tr("Propuesta de partner preparada. Sustituye el plan anterior y requiere revisión.", "Partner proposal prepared. It replaces the prior plan and requires review.")); }}>{tr("Preparar propuesta de prueba", "Prepare test proposal")}</button></article>)}</div></>}

        {view === "flow" && actionStep === "creative" && enabledModules.includes("studio") && (action && plan ? <>{actionPicker}<ClubCreativeBrief action={action} lang={lang} brand={brand} campaign={campaign} packages={creativePackages} version={version} channel={channel} onChannel={setChannel} /><section className={styles.panel}><h2>{tr("De la acción a sus piezas", "From action to creative assets")}</h2><p>{tr("Generación local mediante plantillas. Incluye texto editable, gráfico SVG descargable y guion de vídeo. La generación de imágenes por IA, el montaje de vídeos y la publicación requieren proveedores todavía no conectados.", "Local template generation. Includes editable copy, a downloadable SVG graphic and a video script. AI image generation, video rendering and publishing require providers that are not connected yet.")}</p><div className={styles.fields}><label>{tr("Canal del paquete", "Package channel")}<select value={channel} onChange={(event) => { setChannel(event.target.value as Channel); }}><option value="instagram">Instagram · {tr("post y reel", "post and reel")}</option><option value="whatsapp">WhatsApp · {tr("mensaje e imagen", "message and image")}</option><option value="linkedin">LinkedIn · {tr("texto e imagen", "copy and image")}</option></select></label></div>{!approved && <p className={styles.warning}>{tr("Aprueba primero la acción en Preparación.", "Approve the action in Preparation first.")}</p>}<p>{campaign.name[lang]} · {brand.name} · {tr("Kit base y campaña vinculados; el briefing completo está en el archivo exportado.", "Base kit and campaign linked; full brief is in the exported file.")}</p>{campaignBlockers(brand,campaign,date).length > 0 && <p className={styles.warning}>{tr("Revisa vigencia, briefing y contraste en Kits de campaña antes de generar.", "Check validity, brief and contrast in Campaign kits before generating.")}</p>}<button type="button" className={styles.primary} disabled={!editable || !approved || campaignBlockers(brand,campaign,date).length > 0} onClick={makeCreative}>{creative ? tr("Regenerar este paquete de prueba", "Regenerate this test package") : tr("Generar paquete de prueba", "Generate test package")}</button></section>
          {currentCreative && <><section className={styles.panel}><h2>{tr("Texto y composición gráfica", "Copy and graphic composition")}</h2><div className={styles.creativeGrid}><div><label>{tr("Texto de la pieza", "Creative copy")}<textarea rows={8} value={currentCreative.text} maxLength={1500} disabled={!editable} onChange={(event) => { invalidateControls(); setCreative({ ...currentCreative, text: event.target.value, approvedVersion: null }); }} /></label><p>{tr("Editar el texto anula la aprobación de la pieza. El gráfico conserva su titular de plantilla.", "Editing copy invalidates creative approval. The graphic keeps its template headline.")}</p><p><strong>{tr("Formato: ", "Format: ")}</strong>{channel === "instagram" ? "1080 × 1350" : channel === "linkedin" ? "1200 × 627" : "1080 × 1080"} · SVG</p></div><svg ref={svgRef} xmlns="http://www.w3.org/2000/svg" viewBox={channel === "linkedin" ? "0 0 1200 627" : channel === "instagram" ? "0 0 1080 1350" : "0 0 1080 1080"} role="img" aria-label={tr("Composición gráfica de prueba", "Test graphic composition")} className={styles.graphic}><rect width="100%" height="100%" fill={campaign.background} /><rect x="60" y="60" width={channel === "linkedin" ? 1080 : 960} height="100" rx="18" fill={brand.background} /><text x="90" y="125" fill={brand.primary} fontSize="32" fontFamily={brand.font}>{brand.name} · DEMO</text><text x="70" y="260" fill={campaign.primary} fontSize="46" fontWeight="700" fontFamily={brand.font}>{headlineLines(currentCreative.headline)[0]}</text><text x="70" y="310" fill={campaign.primary} fontSize="46" fontWeight="700" fontFamily={brand.font}>{headlineLines(currentCreative.headline)[1]}</text><text x="70" y="350" fill={campaign.primary} fontSize="40" fontFamily={brand.font}>{club}</text><text x="70" y="420" fill={campaign.primary} fontSize="36" fontFamily={brand.font}>{opponent} · {plan.date}</text><text x="70" y="530" fill={campaign.primary} fontSize="27" fontFamily={brand.font}>{tr("Pieza de prueba · sin oferta comercial", "Test creative · no commercial offer")}</text></svg></div><button type="button" onClick={() => download(currentCreative.text, `club-demo-${action.id}-${channel}-copy.txt`, "text/plain;charset=utf-8")}>{tr("Descargar texto de prueba", "Download test copy")}</button><button type="button" onClick={() => { if (svgRef.current) download(new XMLSerializer().serializeToString(svgRef.current), `club-demo-${action.id}-${channel}-creative.svg`, "image/svg+xml;charset=utf-8"); }}>{tr("Descargar gráfico de prueba", "Download test graphic")}</button></section>
          <section className={styles.panel}><h2>{channel === "instagram" ? tr("Guion de reel · 15 segundos", "Reel script · 15 seconds") : tr("Guion audiovisual opcional · 15 segundos", "Optional audiovisual script · 15 seconds")}</h2><ol>{currentCreative.storyboard.map((shot) => <li key={shot}>{shot}</li>)}</ol><p>{tr("Es un guion de producción; no se ha generado un archivo de vídeo. No utiliza rostros, logos ni material del club sin autorización.", "This is a production script; no video file has been generated. It uses no faces, logos or club footage without authorisation.")}</p><button type="button" onClick={() => download(JSON.stringify({ synthetic: true, ...currentCreative, mediaRendered: false }, null, 2), `club-demo-${action.id}-${channel}-brief.json`, "application/json")}>{tr("Descargar briefing creativo", "Download creative brief")}</button></section>
          <section className={styles.panel}><h2>{tr("Revisión y lanzamiento de prueba", "Review and test launch")}</h2><p>{launchControlBlockers.length} {tr("controles pendientes o bloqueados", "pending or blocked controls")}</p><button type="button" onClick={() => go("control")}>{tr("Abrir ficha de control", "Open control review sheet")}</button><label className={styles.check}><input type="checkbox" readOnly checked={approved} />{tr("Acción aprobada para esta configuración", "Action approved for this configuration")}</label><label className={styles.check}><input type="checkbox" readOnly checked={creativeApproved} />{tr("Versión creativa aprobada", "Creative version approved")}</label>{channel === "whatsapp" && <p>{tr("En producción harán falta permisos de contacto, plantilla aprobada cuando corresponda, bajas y un proveedor oficial. Este texto no es una plantilla aprobada por WhatsApp.", "Production requires contact permissions, an approved template where applicable, opt-outs and an official provider. This copy is not a WhatsApp-approved template.")}</p>}{!enabledModules.includes("automation") && <p className={styles.warning}>{tr("Lanzamiento simulado requiere Automatización. Preparar y aprobar una pieza no requiere ese módulo.", "Simulated launch requires Automation. Preparing and approving a creative does not require that module.")}</p>}<div className={styles.actions}><button type="button" disabled={role !== "approver" || !approved || creativeApproved || blockers.length > 0 || !currentCreative.text.trim() || campaignBlockers(brand,campaign,date).length > 0} onClick={approveCreative}>{tr("Aprobar versión creativa de prueba", "Approve test creative version")}</button><button type="button" className={styles.primary} disabled={!canSimulate(action, plan.date, sources, role, currentCreative) || launchControlBlockers.length > 0 || !enabledModules.includes("automation") || campaignBlockers(brand,campaign,date).length > 0} onClick={simulate}>{tr("Simular lanzamiento · sin enviar", "Simulate launch · no delivery")}</button></div><p>{tr("Una aprobación es válida para su versión. No se puede repetir la simulación de lanzamiento de esa misma versión.", "Approval applies to its version. Launch simulation cannot be repeated for that same version.")}</p></section></>}
        </> : empty)}

        {view === "sources" && <><section className={styles.panel}><h2>{tr("Procedencia y disponibilidad", "Provenance and availability")}</h2><p>{tr("Archivo de prueba versionado: siete registros ficticios, dos partners y señales externas inventadas. Puedes simular una fuente desactualizada para comprobar que bloquea la aprobación y el lanzamiento.", "Versioned test file: seven fictional records, two partners and invented external signals. Simulate a stale source to check that it blocks approval and launch.")}</p><button type="button" onClick={() => download(JSON.stringify(sample, null, 2), "club-operations-demo.json", "application/json")}>{tr("Descargar fuentes sintéticas", "Download synthetic sources")}</button></section><div className={styles.cards}>{demoSourceManifest.map((source) => <article className={styles.panel} key={source.id}><h2>{sourceLabels[source.id as SourceId][lang]}</h2><p>{tr("Procedencia: escenario generado para esta demo, sin cuenta externa conectada.", "Provenance: scenario generated for this demo, with no external account connected.")}</p><p>{source.records} {tr("registros de prueba", "test records")}</p><label>{tr("Estado simulado", "Simulated state")}<select value={sources[source.id as SourceId]} disabled={!editable} onChange={(event) => { setSources((previous) => ({ ...previous, [source.id]: event.target.value as SourceState })); log(tr("Fuente modificada. Revisa de nuevo las acciones que dependen de ella.", "Source changed. Review actions that depend on it again.")); }}><option value="ready">{tr("Datos de prueba disponibles", "Test data available")}</option><option value="stale">{tr("Desactualizada", "Stale")}</option><option value="missing">{tr("No disponible", "Unavailable")}</option></select></label></article>)}</div><section className={styles.panel}><h2>{tr("Conexiones de producción pendientes", "Pending production connections")}</h2><ul><li>{tr("Acceso privado y permisos por club; base de datos y auditoría persistente.", "Private access and club permissions; database and persistent audit.")}</li><li>{tr("CRM y ticketing del proveedor real: contrato, documentación y credenciales.", "Actual CRM and ticketing provider: agreement, documentation and credentials.")}</li><li>{tr("Tornos: interfaz autorizada de lectura y reconciliación de accesos.", "Turnstiles: authorised read interface and entry reconciliation.")}</li><li>{tr("Herramientas de tareas, canales de comunicación y cuentas publicitarias.", "Task tools, communication channels and advertising accounts.")}</li><li>{tr("Biblioteca de marca, permisos de uso y proveedores de imagen y vídeo.", "Brand library, usage permissions and image/video providers.")}</li></ul><p>{tr("No se solicitan credenciales ni se cargan datos personales desde esta página pública.", "This public page collects no credentials and uploads no personal data.")}</p></section></>}

        {view === "results" && <><section className={styles.panel}><h2>{tr("Estado de ejecución del ensayo", "Rehearsal execution status")}</h2>{plan ? plan.actions.map((item) => <p key={item.id}><strong>{item.title[lang]}</strong> · {item.simulatedVersion === actionVersion(item, plan.date, sources) ? tr("Simulación local completada", "Local simulation completed") : tr("Sin simulación válida para esta versión", "No valid simulation for this version")}</p>) : <p>{tr("Todavía no hay un plan generado.", "No generated plan yet.")}</p>}<p>{tr("Los siguientes valores son un ejemplo independiente de medición. No son resultados de los clics del ensayo, no varían con cada canal y no corresponden a London City.", "The values below are an independent measurement example. They are not outcomes of rehearsal clicks, do not vary by channel and do not belong to London City.")}</p><div className={styles.metrics}><article><span>{tr("Cohorte de ejemplo", "Example cohort")}</span><strong>{demoMeasurement.eligible}</strong></article><article><span>{tr("Compras ficticias", "Fictional purchases")}</span><strong>{demoMeasurement.purchases}</strong></article><article><span>{tr("Visitas ficticias reconciliadas", "Fictional reconciled visits")}</span><strong>{demoMeasurement.reconciledVisits}</strong></article></div><p><strong>{tr("Impacto incremental: no calculado.", "Incremental impact: not calculated.")}</strong> {tr("Necesita un grupo de comparación válido y resultados reales.", "Requires a valid comparison group and real outcomes.")}</p></section><section className={styles.panel}><h2>{tr("Registro de esta sesión", "Session log")}</h2>{activity.length ? <ol>{activity.map((entry, index) => <li key={index}>{entry}</li>)}</ol> : <p>{tr("No hay actividad registrada.", "No recorded activity.")}</p>}</section></>}
      </section>
    </div>
  </main>;
}
